        ruleTitle: 'Грамматическая основа (Задание 2 ОГЭ · ФИПИ D8AAB6)',
        ruleExplanation:
          '1) Верно: придаточное цели «чтобы ... рассказать» — односоставное безличное предложение, основа «рассказать». 2) Неверно: пропущено подлежащее «путешественник» и второе однородное сказуемое «сталкер» («путешественник — первооткрыватель, «сталкер»»). 3) Неверно: пропущено подлежащее «он», а «путь» — прямое дополнение («он прокладывает»). 4) Верно: подлежащее «это», сказуемое «демонстрирует». 5) Верно: первая часть БСП — «я уяснил».',
        hint: 'В предложении 4 указательное местоимение «это» выступает в роли подлежащего (что? — это демонстрирует).',
