          '(1)Большинство великих географических открытий стало возможным благодаря использованию особых навигационных приборов. (2)Самый известный из них — компас. (3)Он был изобретён в Китае более двух тысяч лет назад. (4)Пластинка из магнитного железняка в этом компасе указывала не на север (как мы привыкли), а на юг, поэтому в Китае компас называли «ведающий югом». (5)После того как в XIII веке знаменитый итальянский путешественник Марко Поло привёз в Европу компас, европейцы сами начали изготавливать этот полезный прибор.',
