ruleExplanation:
'1) Верно: в первой части («Летучие мыши – насекомоядные зверьки...») сказуемое «зверьки» выражено существительным (составное именное сказуемое с нулевой связкой). 2) Неверно: предложение 2 вопросительное по цели высказывания. 3) Верно: придаточное определительное («в комнате какой? где на верёвках... были подвешены колокольчики»). 4) Верно: между первой и второй частями сочинительная связь (союз «но»), а третья присоединена бессоюзно (тире + вводное слово «значит»). 5) Неверно: первая часть («Оказалось») — односоставное безличное предложение, а не неопределённо-личное.',
